/* eslint-disable no-invalid-this */

'use strict';

// MAIN //

/**
* Sets the minimum value in the x-axis scale domain.
*
* @private
* @param {(number|void)} value - input value
* @throws {TypeError} must be a valid value
* @returns {void}
*/
function set( value ) {
	this.xScale.domainMin = value;
}


// EXPORTS //

module.exports = set;
